'use client';

import React, { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { useToast } from '@/components/ui/Toast';
import { MessDayMenu } from '@/types/chat';
import {
  UtensilsCrossed,
  Coffee,
  Sun,
  Sunset,
  Moon,
  Calendar,
  AlertCircle,
  CheckCircle2,
  X,
  MapPin,
  Clock,
  Sparkles,
  FileText,
  Calculator,
  ChevronRight,
  Wrench,
} from 'lucide-react';

interface MessMenuDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  defaultMessSlug?: string;
  onOpenTickets?: (messName: string) => void;
}

const MESSES = [
  { slug: 'pine-mess', name: 'Pine Mess', campus: 'North Campus', location: 'Near Alders (NDH 1)' },
  { slug: 'oak-mess', name: 'Oak Mess', campus: 'North Campus', location: 'North Dining Hall 2' },
  { slug: 'alder-mess', name: 'Alder Mess', campus: 'North Campus', location: 'Alder Hostel Cluster' },
  { slug: 'cedar-mess', name: 'Cedar Mess', campus: 'North Campus', location: 'Cedar Block Complex' },
  { slug: 'maple-mess', name: 'Maple Mess', campus: 'South Campus', location: 'South Dining Hall' },
];

const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'] as const;

export const MessMenuDrawer: React.FC<MessMenuDrawerProps> = ({
  isOpen,
  onClose,
  defaultMessSlug = 'pine-mess',
  onOpenTickets,
}) => {
  const { error, success } = useToast();
  const [selectedMess, setSelectedMess] = useState<string>(defaultMessSlug);
  const [selectedDay, setSelectedDay] = useState<string>('Monday');
  const [menu, setMenu] = useState<MessDayMenu | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'menu' | 'rebate'>('menu');

  // Rebate Form
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [reason, setReason] = useState('Home Visit');
  const [rebateSubmitting, setRebateSubmitting] = useState(false);
  const [submittedRebates, setSubmittedRebates] = useState<
    Array<{ id: string; start: string; end: string; days: number; reason: string; status: string }>
  >([
    {
      id: 'reb-1',
      start: '2026-10-15',
      end: '2026-10-19',
      days: 5,
      reason: 'Diwali Break',
      status: 'Approved by Mess Warden',
    },
  ]);

  useEffect(() => {
    // Pick current day of week on mount
    const daysArr = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const today = daysArr[new Date().getDay()];
    setSelectedDay(today);
  }, []);

  useEffect(() => {
    if (defaultMessSlug) {
      setSelectedMess(defaultMessSlug);
    }
  }, [defaultMessSlug]);

  useEffect(() => {
    if (isOpen) {
      loadMenu(selectedMess);
    }
  }, [isOpen, selectedMess]);

  const loadMenu = async (slug: string) => {
    setLoading(true);
    try {
      const res = await api.getMessMenu(slug);
      if (res.data) {
        setMenu(res.data);
      }
    } catch (err: any) {
      console.error('Failed to load menu:', err);
      error(err.message || 'Could not fetch mess menu');
    } finally {
      setLoading(false);
    }
  };

  const calculateRebateDays = () => {
    if (!startDate || !endDate) return 0;
    const s = new Date(startDate);
    const e = new Date(endDate);
    const diffTime = e.getTime() - s.getTime();
    if (diffTime < 0) return 0;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
    return diffDays;
  };

  const handleApplyRebate = (e: React.FormEvent) => {
    e.preventDefault();
    const days = calculateRebateDays();
    if (days < 3) {
      error('Minimum 3 consecutive days are required to qualify for mess rebate.');
      return;
    }

    setRebateSubmitting(true);
    setTimeout(() => {
      setSubmittedRebates((prev) => [
        {
          id: `reb-${Date.now()}`,
          start: startDate,
          end: endDate,
          days,
          reason,
          status: 'Submitted (Pending Caretaker Review)',
        },
        ...prev,
      ]);
      setRebateSubmitting(false);
      setStartDate('');
      setEndDate('');
      success(`Mess rebate application for ${days} days submitted successfully!`);
    }, 600);
  };

  if (!isOpen) return null;

  const currentMessObj = MESSES.find((m) => m.slug === selectedMess) || MESSES[0];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end bg-black/60 backdrop-blur-sm animate-fade-in">
      <div className="w-full max-w-2xl h-full bg-[#111217] border-l border-white/10 shadow-2xl flex flex-col transform transition-transform duration-300">
        {/* Drawer Header */}
        <div className="p-6 border-b border-white/10 flex items-center justify-between bg-[#161820]/80">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-amber-500/10 text-amber-400 border border-amber-500/20 shadow-inner">
              <UtensilsCrossed size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-xl font-bold text-white tracking-tight">Mess Menu &amp; Rebate</h2>
                <span className="px-2 py-0.5 text-xs font-semibold bg-amber-500/10 text-amber-400 border border-amber-500/20 rounded">
                  {currentMessObj.campus}
                </span>
              </div>
              <p className="text-xs text-white/50 flex items-center gap-1.5 mt-0.5">
                <MapPin size={12} className="text-amber-400/80" />
                {currentMessObj.name} &bull; {currentMessObj.location}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              onClick={onClose}
              className="p-2 rounded-lg text-white/40 hover:text-white hover:bg-white/5 transition-colors"
            >
              <X size={20} />
            </button>
          </div>
        </div>

        {/* Mess Selector & Navigation Bar */}
        <div className="p-4 border-b border-white/5 bg-[#14161f] space-y-3">
          <div className="flex items-center justify-between gap-3 flex-wrap">
            <div className="flex items-center gap-2">
              <label htmlFor="mess-select" className="text-xs font-semibold text-white/60 uppercase tracking-wider">
                Dining Hall:
              </label>
              <select
                id="mess-select"
                value={selectedMess}
                onChange={(e) => setSelectedMess(e.target.value)}
                className="bg-[#1c1e27] border border-white/10 text-white rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:border-amber-500"
              >
                {MESSES.map((m) => (
                  <option key={m.slug} value={m.slug}>
                    {m.name} ({m.campus})
                  </option>
                ))}
              </select>
            </div>

            {/* Sub-tabs: Menu vs Rebates */}
            <div className="flex items-center gap-1 bg-[#1c1e27] p-1 rounded-lg border border-white/5 text-xs">
              <button
                onClick={() => setActiveTab('menu')}
                className={`px-3 py-1.5 rounded-md font-medium transition-all flex items-center gap-1.5 ${
                  activeTab === 'menu'
                    ? 'bg-amber-600 text-white shadow-sm'
                    : 'text-white/50 hover:text-white'
                }`}
              >
                <UtensilsCrossed size={12} /> Today&apos;s Menu
              </button>
              <button
                onClick={() => setActiveTab('rebate')}
                className={`px-3 py-1.5 rounded-md font-medium transition-all flex items-center gap-1.5 ${
                  activeTab === 'rebate'
                    ? 'bg-amber-600 text-white shadow-sm'
                    : 'text-white/50 hover:text-white'
                }`}
              >
                <Calculator size={12} /> Rebate Portal
              </button>
            </div>
          </div>
        </div>

        {/* Tab 1: Menu View */}
        {activeTab === 'menu' && (
          <div className="flex-1 overflow-y-auto flex flex-col">
            {/* Days of Week Filter */}
            <div className="px-6 py-3 border-b border-white/5 bg-[#12141a] flex items-center gap-2 overflow-x-auto">
              {DAYS.map((d) => (
                <button
                  key={d}
                  onClick={() => setSelectedDay(d)}
                  className={`px-3 py-1 rounded-md text-xs font-medium whitespace-nowrap transition-all ${
                    selectedDay === d
                      ? 'bg-amber-500/20 text-amber-300 border border-amber-500/40 shadow-sm'
                      : 'text-white/40 hover:text-white/80'
                  }`}
                >
                  {d}
                </button>
              ))}
            </div>

            {/* Menu Sections */}
            <div className="p-6 space-y-4 flex-1">
              {loading ? (
                <div className="flex flex-col items-center justify-center h-64 text-white/40 gap-3">
                  <div className="w-8 h-8 border-2 border-amber-400 border-t-transparent rounded-full animate-spin" />
                  <p className="text-sm">Fetching daily dining schedule...</p>
                </div>
              ) : (
                <div className="grid grid-cols-1 gap-4">
                  {/* Breakfast */}
                  <div className="bg-[#161822] border border-white/5 rounded-xl p-4.5 hover:border-amber-500/30 transition-all">
                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-white/5">
                      <div className="flex items-center gap-2.5">
                        <div className="p-2 rounded-lg bg-orange-500/10 text-orange-400">
                          <Coffee size={18} />
                        </div>
                        <div>
                          <h4 className="text-sm font-bold text-white">Breakfast</h4>
                          <span className="text-[11px] text-white/40">7:30 AM &ndash; 9:30 AM</span>
                        </div>
                      </div>
                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-white/50">Morning</span>
                    </div>
                    <p className="text-sm text-white/80 leading-relaxed font-medium">
                      {menu?.breakfast || 'Idli, Sambhar, Coconut Chutney, Bread Butter, Sprouts, Milk / Tea'}
                    </p>
                  </div>

                  {/* Lunch */}
                  <div className="bg-[#161822] border border-white/5 rounded-xl p-4.5 hover:border-amber-500/30 transition-all">
                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-white/5">
                      <div className="flex items-center gap-2.5">
                        <div className="p-2 rounded-lg bg-yellow-500/10 text-yellow-400">
                          <Sun size={18} />
                        </div>
                        <div>
                          <h4 className="text-sm font-bold text-white">Lunch</h4>
                          <span className="text-[11px] text-white/40">12:30 PM &ndash; 2:30 PM</span>
                        </div>
                      </div>
                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-white/50">Afternoon</span>
                    </div>
                    <p className="text-sm text-white/80 leading-relaxed font-medium">
                      {menu?.lunch || 'Rajma Masala, Steamed Jeera Rice, Phulka, Boondi Raita, Green Salad'}
                    </p>
                  </div>

                  {/* Evening Snacks */}
                  <div className="bg-[#161822] border border-white/5 rounded-xl p-4.5 hover:border-amber-500/30 transition-all">
                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-white/5">
                      <div className="flex items-center gap-2.5">
                        <div className="p-2 rounded-lg bg-amber-500/10 text-amber-400">
                          <Sunset size={18} />
                        </div>
                        <div>
                          <h4 className="text-sm font-bold text-white">Evening Snacks</h4>
                          <span className="text-[11px] text-white/40">5:00 PM &ndash; 6:00 PM</span>
                        </div>
                      </div>
                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-white/50">Evening</span>
                    </div>
                    <p className="text-sm text-white/80 leading-relaxed font-medium">
                      {menu?.snacks || 'Hot Samosa with Mint Chutney, Biscuits, Hot Tea / Coffee'}
                    </p>
                  </div>

                  {/* Dinner */}
                  <div className="bg-[#161822] border border-white/5 rounded-xl p-4.5 hover:border-amber-500/30 transition-all">
                    <div className="flex items-center justify-between pb-3 mb-3 border-b border-white/5">
                      <div className="flex items-center gap-2.5">
                        <div className="p-2 rounded-lg bg-indigo-500/10 text-indigo-400">
                          <Moon size={18} />
                        </div>
                        <div>
                          <h4 className="text-sm font-bold text-white">Dinner</h4>
                          <span className="text-[11px] text-white/40">7:30 PM &ndash; 9:30 PM</span>
                        </div>
                      </div>
                      <span className="text-xs px-2 py-0.5 rounded bg-white/5 text-white/50">Night</span>
                    </div>
                    <p className="text-sm text-white/80 leading-relaxed font-medium">
                      {menu?.dinner || 'Paneer Butter Masala, Dal Makhani, Tawa Roti, Rice, Gulab Jamun (Sweet)'}
                    </p>
                  </div>
                </div>
              )}

              {/* Action row to file Mess Tickets */}
              <div className="pt-2">
                <div className="p-4 rounded-xl bg-amber-500/5 border border-amber-500/20 flex items-center justify-between gap-4">
                  <div>
                    <h5 className="text-xs font-bold text-white">Notice an issue with food quality or menu shortage?</h5>
                    <p className="text-[11px] text-white/50 mt-0.5">
                      File a ticket for the Mess Warden and Dining Committee to review directly.
                    </p>
                  </div>
                  {onOpenTickets && (
                    <button
                      onClick={() => onOpenTickets(currentMessObj.name)}
                      className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold bg-amber-600 hover:bg-amber-500 text-white transition-all shadow-md whitespace-nowrap"
                    >
                      <Wrench size={12} />
                      Report Mess Issue
                    </button>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Tab 2: Rebate View */}
        {activeTab === 'rebate' && (
          <div className="flex-1 overflow-y-auto p-6 space-y-6">
            {/* Policy Info Card */}
            <div className="p-4 rounded-xl bg-[#161822] border border-white/10 space-y-2">
              <div className="flex items-center gap-2 text-amber-400 font-bold text-sm">
                <AlertCircle size={16} />
                <span>IIT Mandi Mess Rebate Guidelines</span>
              </div>
              <ul className="text-xs text-white/60 space-y-1 list-disc list-inside">
                <li>Minimum rebate duration is <strong className="text-white">3 consecutive days</strong>.</li>
                <li>Applications must be submitted at least <strong className="text-white">48 hours in advance</strong>.</li>
                <li>Rebate amount is calculated @ ₹140/day and credited directly to the next semester mess billing ledger.</li>
              </ul>
            </div>

            {/* Application Form */}
            <form onSubmit={handleApplyRebate} className="bg-[#14161f] border border-white/5 rounded-xl p-5 space-y-4">
              <h4 className="text-sm font-bold text-white flex items-center gap-2">
                <Calendar size={16} className="text-amber-400" />
                Apply for Mess Rebate
              </h4>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="rebate-from-date" className="block text-xs font-medium text-white/60 mb-1">From Date</label>
                  <input
                    id="rebate-from-date"
                    type="date"
                    required
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="w-full bg-[#1c1e27] border border-white/10 rounded-lg px-3 py-2 text-xs text-white focus:outline-none focus:border-amber-500"
                  />
                </div>
                <div>
                  <label htmlFor="rebate-to-date" className="block text-xs font-medium text-white/60 mb-1">To Date</label>
                  <input
                    id="rebate-to-date"
                    type="date"
                    required
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="w-full bg-[#1c1e27] border border-white/10 rounded-lg px-3 py-2 text-xs text-white focus:outline-none focus:border-amber-500"
                  />
                </div>
              </div>

              <div>
                <label htmlFor="rebate-reason" className="block text-xs font-medium text-white/60 mb-1">Reason for Leave</label>
                <select
                  id="rebate-reason"
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  className="w-full bg-[#1c1e27] border border-white/10 rounded-lg px-3 py-2 text-xs text-white focus:outline-none focus:border-amber-500"
                >
                  <option value="Home Visit">Home Visit / Personal Leave</option>
                  <option value="Academic Conference / Fest">Academic Conference / Inter-IIT Fest</option>
                  <option value="Medical Leave">Medical Leave (Approved by Medical Officer)</option>
                  <option value="Internship / Project Work">Official Internship / Project Work</option>
                </select>
              </div>

              {calculateRebateDays() > 0 && (
                <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 text-xs text-amber-300 flex items-center justify-between">
                  <span>Total Duration: <strong>{calculateRebateDays()} days</strong></span>
                  <span>Est. Credit: <strong>₹{calculateRebateDays() * 140}</strong></span>
                </div>
              )}

              <button
                type="submit"
                disabled={rebateSubmitting}
                className="w-full py-2.5 rounded-lg bg-gradient-to-r from-amber-600 to-orange-600 hover:from-amber-500 hover:to-orange-500 text-white text-xs font-bold transition-all shadow-md disabled:opacity-50"
              >
                {rebateSubmitting ? 'Submitting Application...' : 'Submit Rebate Request'}
              </button>
            </form>

            {/* Submitted Applications List */}
            <div className="space-y-3">
              <h5 className="text-xs font-bold uppercase tracking-wider text-white/50">Your Recent Rebates</h5>
              {submittedRebates.map((reb) => (
                <div
                  key={reb.id}
                  className="p-3.5 rounded-xl bg-[#161822] border border-white/5 flex items-center justify-between gap-3 text-xs"
                >
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-semibold text-white">{reb.reason}</span>
                      <span className="text-[11px] text-amber-400 font-mono">({reb.days} days)</span>
                    </div>
                    <div className="text-[11px] text-white/40 mt-0.5">
                      {reb.start} &rarr; {reb.end}
                    </div>
                  </div>
                  <span className="px-2 py-0.5 rounded text-[11px] font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                    {reb.status}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Footer */}
        <div className="p-4 border-t border-white/10 bg-[#14161f] flex items-center justify-between text-xs text-white/50">
          <span>IIT Mandi Dining Affairs Council (DAC)</span>
          <span className="text-amber-400/80 font-medium">Rebate Sync Active</span>
        </div>
      </div>
    </div>
  );
};

