'use client';

import React, { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { useToast } from '@/components/ui/Toast';
import { useAuth } from '@/context/AuthContext';
import { MoodleAssignment } from '@/types/chat';
import {
  GraduationCap,
  RefreshCw,
  ExternalLink,
  Calendar,
  Clock,
  CheckCircle2,
  AlertCircle,
  FileText,
  BookOpen,
  X,
  Bell,
  Sparkles,
  Filter,
  Lock,
} from 'lucide-react';

interface MoodleDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  defaultCourseCode?: string;
  onBroadcastAlert?: (alertText: string) => void;
  isAdmin?: boolean;
}

const COURSES = [
  { code: 'IC152', name: 'Computing & Data Science' },
  { code: 'CS302', name: 'Database Systems' },
  { code: 'EE201', name: 'Signals & Systems' },
  { code: 'IC110', name: 'Electrical Science' },
  { code: 'IC252', name: 'Probability & Statistics' },
  { code: 'IC160', name: 'Engineering Thermodynamics' },
  { code: 'ME301', name: 'Fluid Mechanics' },
  { code: 'CE301', name: 'Structural Analysis' },
  { code: 'DP201', name: 'Design Practicum / ISTP' },
];

export const MoodleDrawer: React.FC<MoodleDrawerProps> = ({
  isOpen,
  onClose,
  defaultCourseCode = 'IC152',
  onBroadcastAlert,
  isAdmin,
}) => {
  const { error, success } = useToast();
  const { profile } = useAuth();
  const [courseCode, setCourseCode] = useState(defaultCourseCode);
  const [assignments, setAssignments] = useState<MoodleAssignment[]>([]);
  const [lastSynced, setLastSynced] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);
  const [activeFilter, setActiveFilter] = useState<'all' | 'pending' | 'submitted' | 'graded'>('all');
  const [selectedType, setSelectedType] = useState<string>('all');

  const roll = profile?.username?.toLowerCase() || '';
  const isCourseAdmin =
    isAdmin !== undefined
      ? isAdmin
      : ['admin', 'gymkhana', 'b22001', 'b23419'].includes(roll) ||
        roll.includes('faculty') ||
        roll.includes('ta_');

  useEffect(() => {
    if (defaultCourseCode) {
      setCourseCode(defaultCourseCode);
    }
  }, [defaultCourseCode]);

  useEffect(() => {
    if (isOpen) {
      loadCourseMoodleData(courseCode);
    }
  }, [isOpen, courseCode]);

  const loadCourseMoodleData = async (code: string) => {
    setLoading(true);
    try {
      const res = await api.getMoodleData(code);
      if (res.data) {
        setAssignments(res.data.assignments || []);
        setLastSynced(res.data.lastSynced || new Date().toISOString());
      }
    } catch (err: any) {
      console.error('Failed to load Moodle data:', err);
      error(err.message || 'Could not fetch Moodle LMS data');
    } finally {
      setLoading(false);
    }
  };

  const handleSync = async () => {
    setSyncing(true);
    try {
      const res = await api.syncMoodle(courseCode);
      if (res.data && res.data.success) {
        success(`Synced successfully with moodle.iitmandi.ac.in!`);
        if (res.data.alert) {
          // If we have broadcast callback, trigger it
          if (onBroadcastAlert) {
            onBroadcastAlert(
              `🤖 **Moodle Bot Alert [${courseCode}]**: New ${res.data.alert.type.toUpperCase()} posted: "${res.data.alert.title}". Due: ${new Date(res.data.alert.dueDate).toLocaleString()} | Weightage: ${res.data.alert.weightage || 'N/A'}`
            );
          }
        }
        await loadCourseMoodleData(courseCode);
      }
    } catch (err: any) {
      error(err.message || 'Failed to trigger LMS sync');
    } finally {
      setSyncing(false);
    }
  };

  if (!isOpen) return null;

  const filteredAssignments = assignments.filter((item) => {
    if (activeFilter !== 'all' && item.status !== activeFilter) return false;
    if (selectedType !== 'all' && item.type !== selectedType) return false;
    return true;
  });

  const getTypeBadge = (type: MoodleAssignment['type']) => {
    switch (type) {
      case 'assignment':
        return <span className="px-2 py-0.5 rounded text-xs font-semibold bg-blue-500/10 text-blue-400 border border-blue-500/20">Assignment</span>;
      case 'quiz':
        return <span className="px-2 py-0.5 rounded text-xs font-semibold bg-purple-500/10 text-purple-400 border border-purple-500/20">Quiz</span>;
      case 'lab':
        return <span className="px-2 py-0.5 rounded text-xs font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">Lab Task</span>;
      case 'grade':
        return <span className="px-2 py-0.5 rounded text-xs font-semibold bg-amber-500/10 text-amber-400 border border-amber-500/20">Grades Out</span>;
      case 'announcement':
        return <span className="px-2 py-0.5 rounded text-xs font-semibold bg-rose-500/10 text-rose-400 border border-rose-500/20">Broadcast</span>;
      default:
        return null;
    }
  };

  const getStatusBadge = (status: MoodleAssignment['status']) => {
    switch (status) {
      case 'submitted':
        return (
          <span className="flex items-center gap-1 text-xs text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
            <CheckCircle2 size={12} /> Submitted
          </span>
        );
      case 'graded':
        return (
          <span className="flex items-center gap-1 text-xs text-purple-400 bg-purple-500/10 px-2 py-0.5 rounded-full border border-purple-500/20">
            <Sparkles size={12} /> Graded
          </span>
        );
      case 'pending':
      default:
        return (
          <span className="flex items-center gap-1 text-xs text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded-full border border-amber-500/20">
            <Clock size={12} /> Pending
          </span>
        );
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end bg-black/60 backdrop-blur-sm animate-fade-in">
      <div className="w-full max-w-2xl h-full bg-[#111217] border-l border-white/10 shadow-2xl flex flex-col transform transition-transform duration-300">
        {/* Drawer Header */}
        <div className="p-6 border-b border-white/10 flex items-center justify-between bg-[#161820]/70">
          <div className="flex items-center gap-3">
            <div className="p-2.5 rounded-xl bg-purple-500/10 text-purple-400 border border-purple-500/20 shadow-inner">
              <GraduationCap size={24} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-xl font-bold text-white tracking-tight">IIT Mandi Moodle LMS</h2>
                <span className="px-2 py-0.5 text-xs font-semibold bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 rounded">
                  Live Sync
                </span>
              </div>
              <p className="text-xs text-white/50">
                Connected to <span className="text-purple-400">moodle.iitmandi.ac.in</span>
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg text-white/40 hover:text-white hover:bg-white/5 transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        {/* Sync Status Banner & Course Selector */}
        <div className="p-4 border-b border-white/5 bg-[#14161f] space-y-3">
          <div className="flex items-center justify-between gap-3 flex-wrap">
            <div className="flex items-center gap-2">
              <label htmlFor="course-select" className="text-xs font-semibold text-white/60 uppercase tracking-wider">
                Select Course:
              </label>
              <select
                id="course-select"
                value={courseCode}
                onChange={(e) => setCourseCode(e.target.value)}
                className="bg-[#1c1e27] border border-white/10 text-white rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:border-purple-500"
              >
                {COURSES.map((c) => (
                  <option key={c.code} value={c.code}>
                    {c.code} - {c.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="flex items-center gap-2">
              {isCourseAdmin ? (
                <button
                  onClick={handleSync}
                  disabled={syncing}
                  className="flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-semibold bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 text-white shadow-md transition-all active:scale-95 disabled:opacity-50"
                >
                  <RefreshCw size={13} className={syncing ? 'animate-spin' : ''} />
                  {syncing ? 'Syncing...' : 'Sync Moodle Now'}
                </button>
              ) : (
                <div
                  className="flex items-center gap-1.5 px-2.5 py-1 rounded bg-white/5 text-[11px] text-white/50 border border-white/10"
                  title="Only Course Instructors and TAs can trigger manual LMS webhook sync"
                >
                  <Lock size={12} className="text-purple-400" />
                  <span>Read-Only LMS View</span>
                </div>
              )}

              <a
                href="https://moodle.iitmandi.ac.in"
                target="_blank"
                rel="noreferrer"
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold text-white/70 hover:text-white bg-white/5 hover:bg-white/10 border border-white/10 transition-colors"
              >
                <ExternalLink size={13} />
                Portal
              </a>
            </div>
          </div>

          <div className="flex items-center justify-between text-xs text-white/40 pt-1">
            <span>
              Last webhook sync: {lastSynced ? new Date(lastSynced).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : 'Just now'}
            </span>
            <span className="flex items-center gap-1 text-purple-400/80">
              <Bell size={12} /> Auto-broadcasts enabled for #{courseCode}
            </span>
          </div>
        </div>

        {/* Filter Toolbar */}
        <div className="px-6 py-3 border-b border-white/5 bg-[#12141a] flex items-center justify-between gap-3 overflow-x-auto">
          {/* Status Tabs */}
          <div className="flex items-center gap-1 bg-[#1a1c24] p-1 rounded-lg border border-white/5 text-xs">
            {(['all', 'pending', 'submitted', 'graded'] as const).map((st) => (
              <button
                key={st}
                onClick={() => setActiveFilter(st)}
                className={`px-3 py-1 rounded-md capitalize font-medium transition-all ${
                  activeFilter === st
                    ? 'bg-purple-600 text-white shadow-sm'
                    : 'text-white/50 hover:text-white'
                }`}
              >
                {st}
              </button>
            ))}
          </div>

          {/* Type Filter */}
          <div className="flex items-center gap-2">
            <Filter size={13} className="text-white/40" />
            <select
              value={selectedType}
              onChange={(e) => setSelectedType(e.target.value)}
              className="bg-[#1a1c24] border border-white/10 text-white/70 text-xs rounded-md px-2 py-1 focus:outline-none focus:border-purple-500"
            >
              <option value="all">All Types</option>
              <option value="assignment">Assignments</option>
              <option value="quiz">Quizzes</option>
              <option value="lab">Labs</option>
              <option value="grade">Grades</option>
              <option value="announcement">Announcements</option>
            </select>
          </div>
        </div>

        {/* Assignments / Broadcast List */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {loading ? (
            <div className="flex flex-col items-center justify-center h-64 text-white/40 gap-3">
              <RefreshCw className="animate-spin text-purple-400" size={28} />
              <p className="text-sm">Fetching course data from moodle.iitmandi.ac.in...</p>
            </div>
          ) : filteredAssignments.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-center p-6 border border-dashed border-white/10 rounded-2xl bg-[#14161f]/50">
              <BookOpen size={36} className="text-white/20 mb-3" />
              <p className="text-sm font-semibold text-white/70">No Moodle Items Found</p>
              <p className="text-xs text-white/40 mt-1 max-w-xs">
                No active tasks or announcements match your filter for {courseCode}. Click &quot;Sync Moodle Now&quot; to fetch fresh updates!
              </p>
            </div>
          ) : (
            filteredAssignments.map((item) => {
              const due = new Date(item.dueDate);
              const isPast = due.getTime() < Date.now();

              return (
                <div
                  key={item.id}
                  className="bg-[#161822] border border-white/5 hover:border-purple-500/30 rounded-xl p-4 transition-all duration-200 hover:shadow-lg hover:shadow-purple-950/20 group"
                >
                  <div className="flex items-start justify-between gap-3 mb-2">
                    <div className="flex items-center gap-2 flex-wrap">
                      {getTypeBadge(item.type)}
                      <span className="text-xs font-mono font-bold text-purple-300">
                        {item.courseCode}
                      </span>
                      {item.weightage && (
                        <span className="text-[11px] font-medium text-white/40 bg-white/5 px-2 py-0.5 rounded">
                          Weight: {item.weightage}
                        </span>
                      )}
                    </div>
                    {getStatusBadge(item.status)}
                  </div>

                  <h3 className="text-sm font-semibold text-white group-hover:text-purple-300 transition-colors">
                    {item.title}
                  </h3>

                  <p className="text-xs text-white/60 mt-1.5 leading-relaxed">
                    {item.description}
                  </p>

                  <div className="mt-4 pt-3 border-t border-white/5 flex items-center justify-between text-xs flex-wrap gap-2">
                    <div className="flex items-center gap-1.5 text-white/50">
                      <Clock size={12} className={isPast ? 'text-rose-400' : 'text-amber-400'} />
                      <span className={isPast ? 'text-rose-400/90 font-medium' : ''}>
                        {isPast ? 'Closed: ' : 'Due: '}
                        {due.toLocaleDateString(undefined, {
                          month: 'short',
                          day: 'numeric',
                          weekday: 'short',
                        })}{' '}
                        at{' '}
                        {due.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>

                    <div className="flex items-center gap-2">
                      {onBroadcastAlert && isCourseAdmin && (
                        <button
                          onClick={() => {
                            onBroadcastAlert(
                              `🔔 **Moodle Alert [${item.courseCode}]**: ${item.title} - Due ${due.toLocaleString()}`
                            );
                            success(`Broadcasted to #${item.courseCode} chat!`);
                          }}
                          className="flex items-center gap-1 px-2.5 py-1 rounded bg-white/5 hover:bg-white/10 text-[11px] text-white/70 hover:text-white transition-colors"
                          title="Broadcast to current chat"
                        >
                          <Bell size={11} /> Broadcast
                        </button>
                      )}

                      <a
                        href={item.moodleUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="flex items-center gap-1 px-2.5 py-1 rounded bg-purple-600/20 hover:bg-purple-600/40 text-purple-300 text-[11px] font-medium border border-purple-500/30 transition-colors"
                      >
                        <ExternalLink size={11} />
                        Open on Moodle
                      </a>
                    </div>
                  </div>
                </div>
              );
            })
          )}
        </div>

        {/* Footer Info */}
        <div className="p-4 border-t border-white/10 bg-[#14161f] flex items-center justify-between text-xs text-white/50">
          <span>IIT Mandi LMS Webhook v2.4</span>
          <span className="flex items-center gap-1.5 text-white/40">
            <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
            Moodle Daemon Healthy
          </span>
        </div>
      </div>
    </div>
  );
};

'use client';

import React from 'react';
import { useChat } from '@/context/ChatContext';
import { useAuth } from '@/context/AuthContext';
import { Avatar } from '@/components/ui/Avatar';
import {
  getConversationMembers,
  getOtherMember,
  getMemberProfile,
} from '@/lib/utils';
import {
  Search,
  Info,
  ChevronLeft,
  Users,
  Calendar,
  Wrench,
  GraduationCap,
  UtensilsCrossed,
  Sparkles,
  MapPin,
  ShieldCheck,
} from 'lucide-react';
import { ALL_CAMPUS_ROOMS, getCategoryBadge, isCampusRoomAdmin } from '@/lib/campus-rooms';

interface ChatHeaderProps {
  onBackMobile: () => void;
  onOpenSearch: () => void;
  onOpenInfo: () => void;
  onOpenCalendar?: (organizer?: string, isAdmin?: boolean) => void;
  onOpenTickets?: (scope?: 'hostel' | 'mess', clusterOrMess?: string, isAdmin?: boolean) => void;
  onOpenMoodle?: (courseCode?: string, isAdmin?: boolean) => void;
  onOpenMessMenu?: (messSlug?: string, isAdmin?: boolean) => void;
}

export const ChatHeader: React.FC<ChatHeaderProps> = ({
  onBackMobile,
  onOpenSearch,
  onOpenInfo,
  onOpenCalendar,
  onOpenTickets,
  onOpenMoodle,
  onOpenMessMenu,
}) => {
  const { activeConversation, typingUserIds } = useChat();
  const { user, profile } = useAuth();

  if (!activeConversation) return null;

  const isDirect = activeConversation.type === 'direct';
  const members = getConversationMembers(activeConversation);
  const otherMember = getOtherMember(activeConversation, user?.id);
  const otherProfile = getMemberProfile(otherMember);

  const currentMember = members.find((m) => m.user_id === user?.id);
  const isConvOwnerOrAdmin = currentMember?.role === 'owner' || currentMember?.role === 'admin';

  let title = activeConversation.title || 'Conversation';
  let subtitle = '';
  let avatarName = title;
  let avatarKey: string | null = null;

  // Identify if this conversation is a campus scoped room
  const normalizedTitle = title.replace(/^#/, '').toLowerCase().trim();
  const campusRoom = ALL_CAMPUS_ROOMS.find(
    (r) =>
      r.name.toLowerCase() === normalizedTitle ||
      r.slug.toLowerCase() === normalizedTitle ||
      (r.courseCode && normalizedTitle.includes(r.courseCode.toLowerCase()))
  );

  const isCampusAdmin = campusRoom
    ? isCampusRoomAdmin(campusRoom.slug, user) ||
      isCampusRoomAdmin(campusRoom.slug, profile?.username)
    : false;
  const isRoomAdmin = Boolean(isConvOwnerOrAdmin || isCampusAdmin);

  if (isDirect) {
    if (otherProfile) {
      title = otherProfile.display_name || otherProfile.username || 'Student';
      avatarName = title;
      avatarKey = otherProfile.avatar_key;
      const rollTag = otherProfile.username ? `@${otherProfile.username.toUpperCase()}` : '';
      subtitle =
        typingUserIds.length > 0
          ? 'typing...'
          : `${rollTag} • IIT Mandi`;
    } else {
      title = 'Student';
      avatarName = title;
      subtitle = 'Intracampus Direct Chat';
    }
  } else if (campusRoom) {
    title = `#${campusRoom.name}`;
    avatarName = campusRoom.name;
    const activeCount = members.filter((m) => !m.left_at).length || 0;
    subtitle =
      typingUserIds.length > 0
        ? `${typingUserIds.length} member(s) typing...`
        : `${campusRoom.subcategory} • ${campusRoom.campus || 'North/South'} Campus`;
  } else {
    const activeCount = members.filter((m) => !m.left_at).length || 0;
    subtitle =
      typingUserIds.length > 0
        ? `${typingUserIds.length} member(s) typing...`
        : `${activeCount} members • Kamand Group`;
  }

  return (
    <div className="chat-header">
      <div className="chat-header-info">
        {/* Mobile back arrow */}
        <button
          onClick={onBackMobile}
          className="btn-icon btn-ghost"
          style={{ display: 'none' }}
          id="btn-mobile-back"
          title="Back to conversation list"
        >
          <ChevronLeft size={20} />
        </button>

        {isDirect ? (
          <Avatar name={avatarName} src={avatarKey} size="md" online={true} />
        ) : campusRoom ? (
          <div
            onClick={onOpenInfo}
            style={{
              width: 40,
              height: 40,
              minWidth: 40,
              borderRadius: '12px',
              background: 'linear-gradient(135deg, rgba(99, 102, 241, 0.3) 0%, rgba(168, 85, 247, 0.3) 100%)',
              border: '1px solid rgba(168, 85, 247, 0.4)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#c084fc',
              fontWeight: 'bold',
              fontSize: '18px',
              fontFamily: 'monospace',
              cursor: 'pointer',
              boxShadow: '0 2px 10px rgba(99, 102, 241, 0.2)',
            }}
          >
            #
          </div>
        ) : (
          <div
            onClick={onOpenInfo}
            style={{
              width: 40,
              height: 40,
              borderRadius: '50%',
              background: 'linear-gradient(135deg, #0284c7 0%, #6366f1 100%)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#ffffff',
              cursor: 'pointer',
            }}
          >
            <Users size={18} />
          </div>
        )}

        <div
          className="chat-title-group"
          onClick={!isDirect ? onOpenInfo : undefined}
          style={{ cursor: !isDirect ? 'pointer' : 'default' }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap' }}>
            <h2 className="chat-title">{title}</h2>
            {campusRoom && (
              <span
                style={{
                  fontSize: '11px',
                  fontWeight: 600,
                  padding: '2px 8px',
                  borderRadius: '6px',
                  backgroundColor: 'rgba(99, 102, 241, 0.15)',
                  color: '#a5b4fc',
                  border: '1px solid rgba(99, 102, 241, 0.3)',
                }}
              >
                {campusRoom.category.toUpperCase()}
              </span>
            )}
            {!isDirect && isRoomAdmin && (
              <span
                style={{
                  fontSize: '11px',
                  fontWeight: 600,
                  padding: '2px 8px',
                  borderRadius: '6px',
                  backgroundColor: 'rgba(234, 179, 8, 0.15)',
                  color: '#facc15',
                  border: '1px solid rgba(234, 179, 8, 0.3)',
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: '4px',
                }}
                title="You have administrative privileges in this room"
              >
                <ShieldCheck size={11} /> Admin
              </span>
            )}
          </div>
          <span
            className="chat-subtitle"
            style={{
              color: typingUserIds.length > 0 ? 'var(--accent)' : 'var(--text-secondary)',
            }}
          >
            {subtitle}
          </span>
        </div>
      </div>

      <div className="chat-header-actions" style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
        {/* Contextual Action Buttons for Scoped Campus Rooms */}
        {campusRoom && (
          <>
            {/* Clubs & Branches & Fests: Calendar & Venue Booking */}
            {(campusRoom.category === 'clubs' || campusRoom.category === 'branches') && onOpenCalendar && (
              <button
                onClick={() => onOpenCalendar(campusRoom.name, isRoomAdmin)}
                className="btn btn-secondary"
                style={{
                  padding: '6px 10px',
                  fontSize: '12px',
                  borderRadius: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                  background: 'rgba(99, 102, 241, 0.15)',
                  borderColor: 'rgba(99, 102, 241, 0.3)',
                  color: '#c7d2fe',
                }}
                title="Unified Gymkhana Calendar & Venue Bookings"
              >
                <Calendar size={14} className="text-indigo-400" />
                <span className="hidden-mobile">Gymkhana Calendar</span>
              </button>
            )}

            {/* Courses: Moodle LMS Sync & Assignments */}
            {campusRoom.category === 'courses' && onOpenMoodle && (
              <button
                onClick={() => onOpenMoodle(campusRoom.courseCode || 'IC152', isRoomAdmin)}
                className="btn btn-secondary"
                style={{
                  padding: '6px 10px',
                  fontSize: '12px',
                  borderRadius: '8px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                  background: 'rgba(168, 85, 247, 0.15)',
