              const senderName =
                sender?.profiles?.display_name ||
                sender?.profiles?.username ||
                'User';

              return (
                <div
                  key={msg.id}
                  style={{
                    padding: '10px 14px',
                    borderRadius: 'var(--radius-md)',
                    background: 'rgba(255, 255, 255, 0.03)',
                    border: '1px solid var(--border-subtle)',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '4px',
