            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: '6px 4px',
              borderRadius: '8px',
              fontSize: '10px',
              gap: '4px',
              background: 'rgba(56, 189, 248, 0.08)',
              color: '#bae6fd',
              border: '1px solid rgba(56, 189, 248, 0.15)',
            }}
            title="Hostel & Mess Maintenance Tickets"
          >
            <Wrench size={14} className="text-sky-400" />
            <span>Tickets</span>
          </button>

          <button
            onClick={() => onOpenMoodle?.()}
            className="btn btn-ghost"
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: '6px 4px',
              borderRadius: '8px',
              fontSize: '10px',
              gap: '4px',
              background: 'rgba(168, 85, 247, 0.08)',
              color: '#e9d5ff',
              border: '1px solid rgba(168, 85, 247, 0.15)',
            }}
            title="IIT Mandi Moodle LMS Sync"
          >
            <GraduationCap size={14} className="text-purple-400" />
            <span>Moodle</span>
          </button>

          <button
            onClick={() => onOpenMessMenu?.()}
            className="btn btn-ghost"
            style={{
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              padding: '6px 4px',
              borderRadius: '8px',
              fontSize: '10px',
              gap: '4px',
              background: 'rgba(245, 158, 11, 0.08)',
              color: '#fde68a',
              border: '1px solid rgba(245, 158, 11, 0.15)',
            }}
            title="Mess Menus & Rebate Portal"
          >
            <UtensilsCrossed size={14} className="text-amber-400" />
            <span>Messes</span>
          </button>
        </div>

        {/* 6 Category Switcher Navigation Tabs */}
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            padding: '8px 14px 4px',
            gap: '4px',
            overflowX: 'auto',
          }}
        >
          <button
            onClick={() => {
              setMainTab('dms');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'dms' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '11.5px' }}
          >
            DMs ({conversations.length})
          </button>
          <button
            onClick={() => {
              setMainTab('clubs');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'clubs' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '11.5px' }}
          >
            Clubs
          </button>
          <button
            onClick={() => {
              setMainTab('courses');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'courses' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '11.5px' }}
          >
            Courses
          </button>
          <button
            onClick={() => {
              setMainTab('hostels');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'hostels' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '11.5px' }}
          >
            Hostels
          </button>
          <button
            onClick={() => {
              setMainTab('branches');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'branches' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '11.5px' }}
          >
            Branches
          </button>
          <button
            onClick={() => {
              setMainTab('messes');
              setSubFilter('all');
            }}
            className={`nav-pill ${mainTab === 'messes' ? 'active' : ''}`}
            style={{ whiteSpace: 'nowrap', padding: '5px 10px', fontSize: '11.5px' }}
          >
            Messes
          </button>
        </div>

        {/* Sub-Filters / Pills for Selected Category */}
        <div style={{ display: 'flex', padding: '2px 16px 8px', gap: '6px', overflowX: 'auto' }}>
          {mainTab === 'dms' && (
            <>
              <button
                className={`nav-pill ${filterType === 'all' ? 'active' : ''}`}
                onClick={() => setFilterType('all')}
                style={{ fontSize: '11px', padding: '3px 8px' }}
              >
                All
              </button>
              <button
                className={`nav-pill ${filterType === 'direct' ? 'active' : ''}`}
                onClick={() => setFilterType('direct')}
                style={{ fontSize: '11px', padding: '3px 8px' }}
              >
                Direct
              </button>
              <button
                className={`nav-pill ${filterType === 'group' ? 'active' : ''}`}
                onClick={() => setFilterType('group')}
                style={{ fontSize: '11px', padding: '3px 8px' }}
              >
                Groups
              </button>
            </>
          )}

          {mainTab === 'clubs' && (
            <>
              {['all', 'SnTC', 'SAC', 'Sports', 'Fest'].map((f) => (
                <button
                  key={f}
                  className={`nav-pill ${subFilter === f ? 'active' : ''}`}
                  onClick={() => setSubFilter(f)}
                  style={{ fontSize: '11px', padding: '3px 8px' }}
                >
                  {f === 'all' ? 'All Clubs' : f}
                </button>
              ))}
            </>
          )}

          {mainTab === 'courses' && (
            <>
              {[
                { id: 'all', label: 'All Courses' },
                { id: 'core', label: 'Institute Core' },
                { id: 'dept', label: 'Dept Core' },
                { id: 'practicum', label: 'Practicum' },
              ].map((f) => (
                <button
                  key={f.id}
                  className={`nav-pill ${subFilter === f.id ? 'active' : ''}`}
                  onClick={() => setSubFilter(f.id)}
                  style={{ fontSize: '11px', padding: '3px 8px' }}
                >
                  {f.label}
                </button>
              ))}
            </>
          )}

          {mainTab === 'hostels' && (
            <>
              {[
                { id: 'all', label: 'All Hostels' },
                { id: 'North', label: 'North Campus' },
                { id: 'South', label: 'South Campus' },
                { id: 'clusters', label: 'General / Clusters' },
              ].map((f) => (
                <button
                  key={f.id}
                  className={`nav-pill ${subFilter === f.id ? 'active' : ''}`}
                  onClick={() => setSubFilter(f.id)}
                  style={{ fontSize: '11px', padding: '3px 8px' }}
                >
                  {f.label}
                </button>
              ))}
            </>
          )}

          {mainTab === 'branches' && (
            <>
              {[
                { id: 'all', label: 'All Programs' },
                { id: 'btech', label: 'B.Tech' },
                { id: 'dual', label: 'Dual / BS' },
                { id: 'pg', label: 'PG / Masters' },
