import { io, Socket } from 'socket.io-client';
import { api } from './api';

const SOCKET_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:4000';

type Listener = (...args: any[]) => void;

class SocketManager {
  private socket: Socket | null = null;
  private listeners: Map<string, Set<Listener>> = new Map();
  private lastTypingSent: number = 0;
  private isConnecting: boolean = false;

  connect(token: string) {
    if (this.socket && this.socket.connected) {
      if ((this.socket.auth as any)?.token === token) {
        return;
      }
      this.disconnect();
    }

    if (this.isConnecting) return;
    this.isConnecting = true;

    this.socket = io(SOCKET_URL, {
      transports: ['websocket'],
      auth: { token },
      reconnection: true,
      reconnectionAttempts: 10,
      reconnectionDelay: 1000,
      reconnectionDelayMax: 5000,
    });

    this.socket.on('connect', () => {
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: true, status: 'connected' });
    });

    this.socket.on('disconnect', (reason) => {
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: false, status: 'disconnected', reason });
    });

    this.socket.on('connect_error', (err) => {
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: false, status: 'error', error: err.message });
    });

    // Real-time server events
    const serverEvents = [
      'message:new',
      'message:updated',
      'message:deleted',
      'message:reaction',
      'conversation:updated',
      'conversation:removed',
      'conversation:read',
      'typing',
      'session:expired',
    ];

    for (const eventName of serverEvents) {
      this.socket.on(eventName, (payload: any) => {
        if (eventName === 'session:expired') {
          // Token expired, attempt refresh
          api.refreshTokenIfNeeded().then((newToken) => {
            if (newToken && this.socket) {
              this.socket.auth = { token: newToken };
              this.socket.disconnect().connect();
            }
          });
        }
        this.dispatch(eventName, payload);
      });
    }
  }

  updateToken(token: string) {
    if (this.socket) {
      this.socket.auth = { token };
      this.socket.disconnect().connect();
    }
  }

  disconnect() {
    if (this.socket) {
      this.socket.disconnect();
      this.socket = null;
      this.isConnecting = false;
      this.dispatch('connection:status', { connected: false, status: 'disconnected' });
    }
  }

  on(event: string, listener: Listener) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(listener);
    return () => this.off(event, listener);
  }

  off(event: string, listener: Listener) {
    const set = this.listeners.get(event);
    if (set) {
      set.delete(listener);
    }
  }

  private dispatch(event: string, ...args: any[]) {
    const set = this.listeners.get(event);
    if (set) {
      for (const listener of set) {
        try {
          listener(...args);
        } catch (err) {
          console.error(`Error in socket event listener [${event}]:`, err);
        }
      }
    }
  }

  emitTyping(conversationId: string, isTyping: boolean) {
    if (!this.socket || !this.socket.connected) return;

    const now = Date.now();
    // Throttle positive typing events to once per second
    if (isTyping && now - this.lastTypingSent < 1000) {
      return;
    }

    if (isTyping) {
      this.lastTypingSent = now;
    }

    this.socket.emit(
      'typing',
      { conversation_id: conversationId, is_typing: isTyping },
      (ack: { ok: boolean; error?: string }) => {
        // Ack received
      }
    );
  }

  isConnected(): boolean {
    return !!this.socket?.connected;
  }
}

export const socketManager = new SocketManager();

// Utility functions for UI formatting, avatars, and animations

export function formatTime(isoString: string): string {
  try {
    const date = new Date(isoString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  } catch {
    return '';
  }
}

export function formatDateDivider(isoString: string): string {
  try {
    const date = new Date(isoString);
    const now = new Date();
    const isToday =
      date.getDate() === now.getDate() &&
      date.getMonth() === now.getMonth() &&
      date.getFullYear() === now.getFullYear();

    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    const isYesterday =
      date.getDate() === yesterday.getDate() &&
      date.getMonth() === yesterday.getMonth() &&
      date.getFullYear() === yesterday.getFullYear();

    if (isToday) return 'Today';
    if (isYesterday) return 'Yesterday';

    return date.toLocaleDateString([], {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined,
    });
  } catch {
    return '';
  }
}

export function formatTimeAgo(isoString: string): string {
  try {
    const date = new Date(isoString);
    const now = new Date();
    const diffSec = Math.floor((now.getTime() - date.getTime()) / 1000);

    if (diffSec < 60) return 'Just now';
    if (diffSec < 3600) return `${Math.floor(diffSec / 60)}m ago`;
    if (diffSec < 86400) return `${Math.floor(diffSec / 3600)}h ago`;
    if (diffSec < 604800) return `${Math.floor(diffSec / 86400)}d ago`;

    return date.toLocaleDateString([], { month: 'short', day: 'numeric' });
  } catch {
    return '';
  }
}

export function formatFileSize(bytes: number): string {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return `${parseFloat((bytes / Math.pow(k, i)).toFixed(1))} ${sizes[i]}`;
}

export function getInitials(name?: string | null): string {
  if (!name) return '?';
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) {
    return parts[0].slice(0, 2).toUpperCase();
  }
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

const GRADIENTS = [
  'linear-gradient(135deg, #6366f1 0%, #a855f7 100%)',
  'linear-gradient(135deg, #3b82f6 0%, #2dd4bf 100%)',
  'linear-gradient(135deg, #ec4899 0%, #8b5cf6 100%)',
  'linear-gradient(135deg, #f97316 0%, #eab308 100%)',
  'linear-gradient(135deg, #06b6d4 0%, #3b82f6 100%)',
  'linear-gradient(135deg, #10b981 0%, #06b6d4 100%)',
  'linear-gradient(135deg, #8b5cf6 0%, #ec4899 100%)',
  'linear-gradient(135deg, #f43f5e 0%, #fb923c 100%)',
];

export function getAvatarGradient(identifier: string): string {
  let hash = 0;
  for (let i = 0; i < identifier.length; i++) {
    hash = identifier.charCodeAt(i) + ((hash << 5) - hash);
  }
  const index = Math.abs(hash) % GRADIENTS.length;
  return GRADIENTS[index];
}

export function truncate(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text;
  return text.slice(0, maxLength) + '...';
}

export function generateUUID(): string {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) {
    return crypto.randomUUID();
  }
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

export function getMemberProfile(member?: any): { id: string; username: string; display_name: string; avatar_key: string | null } | null {
  if (!member) return null;
  if (member.profiles) {
    return Array.isArray(member.profiles) ? member.profiles[0] : member.profiles;
  }
  if (member.profile) {
    return Array.isArray(member.profile) ? member.profile[0] : member.profile;
  }
  return null;
}

export function getConversationMembers(conv?: any): any[] {
  if (!conv) return [];
  return conv.conversation_members || conv.members || [];
}

export function getOtherMember(conv?: any, currentUserId?: string): any | null {
  const members = getConversationMembers(conv);
  return members.find((m: any) => m.user_id !== currentUserId) || null;
}
